def parse_fraud_range(fraud_str):
    """Parse fraud level string like '7.7%-8.3%', '>8.3%', '<5%' to comparison function"""
    if not fraud_str:
        return None

    fraud_str = fraud_str.strip().replace('%', '')

    if '-' in fraud_str and not fraud_str.startswith('-'):  # two-sided range
        parts = fraud_str.split('-')
        low = float(parts[0].strip())
        high = float(parts[1].strip())
        return (low, high, 'range')
    elif fraud_str.startswith('>'):
        return (float(fraud_str[1:].strip()), None, 'greater')
    elif fraud_str.startswith('<'):
        return (float(fraud_str[1:].strip()), None, 'less')
    else:
        val = float(fraud_str)
        return (val, val, 'range')

def parse_volume_range(volume_str):
    """Parse volume string like '100k-1m', '>5m', '<100k' to comparison function"""
    if not volume_str:
        return None

    volume_str = volume_str.strip()

    def parse_value(s):
        s = s.strip()
        multipliers = {'k': 1000, 'm': 1000000}
        for suffix, mult in multipliers.items():
            if s.lower().endswith(suffix):
                return float(s[:-1]) * mult
        return float(s)

    if '-' in volume_str and not volume_str.startswith('-'):  # two-sided range
        parts = volume_str.split('-')
        low = parse_value(parts[0])
        high = parse_value(parts[1])
        return (low, high, 'range')
    elif volume_str.startswith('>'):
        return (parse_value(volume_str[1:]), None, 'greater')
    elif volume_str.startswith('<'):
        return (parse_value(volume_str[1:]), None, 'less')
    else:
        val = parse_value(volume_str)
        return (val, val, 'range')

